#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

using namespace std;

// Function to count the occurrences of a word in a file
int countWordOccurrences(const string& filename, const string& word) {
    int count = 0;
    ifstream inputFile(filename); // Open the file for reading

    if (!inputFile.is_open()) {
        cerr << "Error opening file: " << filename << endl;
        return -1; // Indicate an error
    }

    string line;
    while (getline(inputFile, line)) { // Read the file line by line
        // Use stringstream to easily iterate through words in the line
        stringstream ss(line);
        string wordInLine;
        while (ss >> wordInLine) { // Extract each word from the line
            // Convert both the word in the line and the target word to lowercase for case-insensitive comparison
            string lowerWordInLine = wordInLine;
            transform(lowerWordInLine.begin(), lowerWordInLine.end(), lowerWordInLine.begin(), ::tolower);
            string lowerTargetWord = word;
            transform(lowerTargetWord.begin(), lowerTargetWord.end(), lowerTargetWord.begin(), ::tolower);

            if (lowerWordInLine == lowerTargetWord) {
                count++; // Increment the count if the words match
            }
        }
    }

    inputFile.close(); // Close the file
    return count;
}

int main() {
    string filename;
    string wordToCount;

    cout << "Enter the filename: ";
    getline(cin, filename); // Use getline to handle filenames with spaces

    cout << "Enter the word to count: ";
    getline(cin, wordToCount);

    int occurrences = countWordOccurrences(filename, wordToCount);

    if (occurrences >= 0) {
        cout << "The word \"" << wordToCount << "\" appears " << occurrences << " times in the file." << endl;
    }

    return 0;
}
